const nextContractVersionNumber = `-- name: NextContractVersionNumber :one

SELECT (COALESCE(max(number), 0) + 1)::int FROM contract_versions WHERE tenant_id = app_tenant_id() AND kind = $1 AND audience = $2
`

type NextContractVersionNumberParams struct {
	Kind     string
	Audience string
}

// Contracts for the seller's customers (internal/contracts). Tenant-scoped, run as plans_app inside pgxx.InTenantTx; the explicit tenant_id = app_tenant_id()
// predicates are belt and braces next to row-level security.
func (q *Queries) NextContractVersionNumber(ctx context.Context, arg NextContractVersionNumberParams) (int32, error) {
	row := q.db.QueryRow(ctx, nextContractVersionNumber, arg.Kind, arg.Audience)
	var column_1 int32
	err := row.Scan(&column_1)
	return column_1, err
}

const referenceAcceptedNumbers = `-- name: ReferenceAcceptedNumbers :many
SELECT kind, audience, max(version_number)::int AS number, COALESCE(max(version_number) FILTER (WHERE immediate_start_consent AND withdrawal_waiver_acknowledged), 0)::int AS consent_number,
  max(accepted_at)::timestamptz AS accepted_at
FROM contract_acceptances WHERE tenant_id = app_tenant_id() AND customer_id IS NULL AND context_ref = $1
GROUP BY kind, audience
`

type ReferenceAcceptedNumbersRow struct {
	Kind          string
	Audience      string
	Number        int32
	ConsentNumber int32
	AcceptedAt    time.Time
}

// The same for a guest: the acceptances made for one invoice.
func (q *Queries) ReferenceAcceptedNumbers(ctx context.Context, contextRef string) ([]ReferenceAcceptedNumbersRow, error) {
	rows, err := q.db.Query(ctx, referenceAcceptedNumbers, contextRef)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ReferenceAcceptedNumbersRow{}
	for rows.Next() {
		var i ReferenceAcceptedNumbersRow
		if err := rows.Scan(
			&i.Kind,
			&i.Audience,
			&i.Number,
			&i.ConsentNumber,
			&i.AcceptedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const setContractWithdrawalRefund = `-- name: SetContractWithdrawalRefund :one
UPDATE contract_withdrawals SET refund_state = $1, credit_note_id = $2, refund_note = $3, refund_at = $4
WHERE tenant_id = app_tenant_id() AND id = $5 RETURNING tenant_id, id, customer_id, subscription_id, invoice_id, statement, source, status, received_at, decided_at, decided_by, decision_note, credit_note_id, refund_state, refund_note, refund_at
`

type SetContractWithdrawalRefundParams struct {
	State        string
	CreditNoteID *uuid.UUID
	Note         string
	Now          *time.Time
	ID           uuid.UUID
}

// The refund of an accepted withdrawal (the caller holds the row lock of GetContractWithdrawalForUpdate and has checked the state).
func (q *Queries) SetContractWithdrawalRefund(ctx context.Context, arg SetContractWithdrawalRefundParams) (ContractWithdrawal, error) {
	row := q.db.QueryRow(ctx, setContractWithdrawalRefund,
		arg.State,
		arg.CreditNoteID,
		arg.Note,
		arg.Now,
		arg.ID,
	)
	var i ContractWithdrawal
	err := row.Scan(
		&i.TenantID,
		&i.ID,
		&i.CustomerID,
		&i.SubscriptionID,
		&i.InvoiceID,
		&i.Statement,
		&i.Source,
		&i.Status,
		&i.ReceivedAt,
		&i.DecidedAt,
		&i.DecidedBy,
		&i.DecisionNote,
		&i.CreditNoteID,
		&i.RefundState,
		&i.RefundNote,
		&i.RefundAt,
	)
	return i, err
}

const settleContractWithdrawalRefund = `-- name: SettleContractWithdrawalRefund :execrows
UPDATE contract_withdrawals SET refund_state = $1, refund_note = $2, refund_at = $3
WHERE tenant_id = app_tenant_id() AND credit_note_id = $4 AND refund_state = ANY($5::text[])
`

type SettleContractWithdrawalRefundParams struct {
	State        string
	Note         string
	Now          *time.Time
	CreditNoteID *uuid.UUID
	FromStates   []string
}

// What the provider did with the refund of a withdrawal's credit note (billing's credit_note.refunded / credit_note.refund_failed events). Only the states in @from_states move, so a
// repeated event, or one that arrives after a later one, changes nothing.
func (q *Queries) SettleContractWithdrawalRefund(ctx context.Context, arg SettleContractWithdrawalRefundParams) (int64, error) {
	result, err := q.db.Exec(ctx, settleContractWithdrawalRefund,
		arg.State,
		arg.Note,
		arg.Now,
		arg.CreditNoteID,
		arg.FromStates,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const upsertContractSettings = `-- name: UpsertContractSettings :one
INSERT INTO contract_settings (tenant_id, required_kinds, immediate_start, retention_months, withdrawal_refund, renewal_notice_days, renewal_cancel_texts, withdrawal_function, updated_at)
VALUES (app_tenant_id(), $1::text[], $2, $3, $4, $5, $6, $7, now())
ON CONFLICT (tenant_id) DO UPDATE SET required_kinds = EXCLUDED.required_kinds, immediate_start = EXCLUDED.immediate_start,
  retention_months = EXCLUDED.retention_months, withdrawal_refund = EXCLUDED.withdrawal_refund, renewal_notice_days = EXCLUDED.renewal_notice_days,
  renewal_cancel_texts = EXCLUDED.renewal_cancel_texts, withdrawal_function = EXCLUDED.withdrawal_function, updated_at = EXCLUDED.updated_at
RETURNING tenant_id, required_kinds, immediate_start, retention_months, updated_at, withdrawal_refund, renewal_notice_days, renewal_cancel_texts, withdrawal_function
`

type UpsertContractSettingsParams struct {
	RequiredKinds      []string
	ImmediateStart     bool
	RetentionMonths    int32
	WithdrawalRefund   string
	RenewalNoticeDays  int32
	RenewalCancelTexts json.RawMessage
	WithdrawalFunction bool
}

func (q *Queries) UpsertContractSettings(ctx context.Context, arg UpsertContractSettingsParams) (ContractSetting, error) {
	row := q.db.QueryRow(ctx, upsertContractSettings,
		arg.RequiredKinds,
		arg.ImmediateStart,
		arg.RetentionMonths,
		arg.WithdrawalRefund,
		arg.RenewalNoticeDays,
		arg.RenewalCancelTexts,
		arg.WithdrawalFunction,
	)
	var i ContractSetting
	err := row.Scan(
		&i.TenantID,
		&i.RequiredKinds,
		&i.ImmediateStart,
		&i.RetentionMonths,
		&i.UpdatedAt,
		&i.WithdrawalRefund,
		&i.RenewalNoticeDays,
		&i.RenewalCancelTexts,
		&i.WithdrawalFunction,
	)
	return i, err
}
